var waits = s.History.Where(e => e.Kind == "unblocked").ToList();
int total = waits.Sum(e => e.Wait);
if (waits.Count == 0)
    Console.WriteLine("waits: none");
else {
    int hundredths = total * 100 / waits.Count;
    Console.WriteLine("waits: " + waits.Count + " unblocked, total " + total +
                      ", average " + hundredths / 100 + "." +
                      (hundredths % 100).ToString("D2"));
